const response = $input.first().json;
const context = $('📝 Tạo Prompt Cho AI Agent').first().json;

let answer = response.candidates?.[0]?.content?.parts?.[0]?.text || '';
answer = String(answer).trim();

if (!answer) {
  answer = 'Em chua tao duoc cau tra loi luc nay. Anh/chi vui long thu lai sau hoac lien he nhan vien tu van.';
}

const suffix = context.handoff_contact
  ? `\n\nNeu anh/chi can nhan vien ho tro truc tiep, vui long lien he: ${context.handoff_contact}`
  : '';

const maxTelegramLength = 3900;
const finalAnswer = (answer + suffix).slice(0, maxTelegramLength);

return [{
  json: {
    chat_id: context.chat_id,
    reply_to_message_id: context.message_id,
    answer: finalAnswer,
    user_message: context.user_message,
    company_name: context.company_name,
    answered_at: new Date().toISOString()
  }
}];
